<script setup>
import TherapistSchedulePanel from './TherapistSchedules.vue'
import { masterConfig } from '../../utils/master-config.js'
import { money, dateLabel, initials } from '#shared/utils/format.js'
const props=defineProps({resource:String,id:String});const config=masterConfig[props.resource]
const {data:record,refresh,error}=await useFetch('/api/'+props.resource+'/'+props.id)
const {isOwner,isOffice,canAssign,isLocationAdmin}=useAuth();const {toast,error:formatError}=useFeedback()
const canEdit=computed(()=>props.resource==='customers'?isOffice.value:['schedules','therapists'].includes(props.resource)?canAssign.value:isOwner.value)
const addressOpen=ref(false);const deleteOpen=ref(false);const busy=ref(false);const message=ref('');const editingAddressId=ref(null)
const address=reactive({label:'Home',address:'',notes:'',isDefault:false,latitude:null,longitude:null})
const addressPin=computed({get:()=>({latitude:address.latitude,longitude:address.longitude}),set:point=>{address.latitude=point?.latitude??null;address.longitude=point?.longitude??null}})
function openAddress(a){editingAddressId.value=a?.id||null;Object.assign(address,{label:a?.label||'Home',address:a?.address||'',notes:a?.notes||'',isDefault:a?.isDefault||false,latitude:a?.latitude??null,longitude:a?.longitude??null});addressOpen.value=true}
async function saveAddress(){busy.value=true;message.value='';try{await $fetch(`/api/customers/${props.id}/addresses`+(editingAddressId.value?'/'+editingAddressId.value:''),{method:editingAddressId.value?'PATCH':'POST',body:address});toast('Alamat disimpan');addressOpen.value=false;await refresh()}catch(e){message.value=formatError(e)}finally{busy.value=false}}
async function remove(){busy.value=true;try{await $fetch('/api/customers/'+props.id,{method:'DELETE'});toast('Customer dihapus');await navigateTo('/customers')}catch(e){message.value=formatError(e)}finally{busy.value=false}}
</script><template><div v-if="record"><LayoutPageHeader :title="record.name||record.therapistName||config.singular" :description="record.email||record.code||record.employeeCode||record.scheduleDate" :eyebrow="config.title"><UiButton v-if="canEdit&&record.canManage!==false" :to="'/'+resource+'/'+id+'/edit'" variant="secondary"><UiIcon name="edit" :size="16" />Edit {{ config.singular }}</UiButton><UiButton :to="'/'+resource" variant="ghost"><UiIcon name="back" :size="16" />Kembali</UiButton></LayoutPageHeader><p v-if="message" class="error-message">{{ message }}</p><template v-if="resource==='customers'"><div class="customer-summary"><div class="panel"><span class="avatar large pastel">{{ initials(record.name) }}</span><div><h2>{{ record.name }}</h2><p>{{ record.phone }}</p><small>{{ record.email||'Email belum ditambahkan' }}</small></div></div><div class="panel"><span>Total orders</span><strong>{{ record.totalOrders }}</strong></div><div class="panel"><span>Total pembayaran</span><strong>{{ money(record.totalSpending) }}</strong></div></div><section class="panel form-panel mt-5"><div class="panel-heading no-pad"><h2>Alamat tersimpan</h2><UiButton v-if="isOffice" variant="secondary" @click="openAddress()"><UiIcon name="plus" :size="16" />Tambah alamat</UiButton></div><div class="address-grid"><div v-for="a in record.addresses" :key="a.id" class="address-box"><UiIcon name="locations" /><div><strong>{{ a.label }} <span v-if="a.isDefault" class="subtle-tag">Utama</span></strong><p>{{ a.address }}</p><small>{{ a.notes }}</small><button v-if="isOffice" class="text-link mt-2" @click="openAddress(a)">Edit alamat</button></div></div><p v-if="!record.addresses.length" class="muted">Belum ada alamat tersimpan.</p></div></section><section class="panel mt-5"><div class="panel-heading"><h2>Riwayat order</h2><UiButton v-if="isOffice" to="/orders/new" variant="secondary">Buat order</UiButton></div><OrderTable :orders="record.orders" /></section><section class="panel form-panel mt-5"><h2>Catatan customer</h2><p class="muted">{{ record.notes||'Belum ada catatan.' }}</p><UiButton v-if="isOffice&&!record.totalOrders" variant="danger" class="mt-4" @click="deleteOpen=true">Hapus customer</UiButton></section></template><section v-else class="panel form-panel master-form"><div class="profile-heading"><span class="avatar large pastel">{{ initials(record.name||record.therapistName) }}</span><div><h2>{{ record.name||record.therapistName }}</h2><UiBadge v-if="record.status" :status="record.status" /></div></div><div class="detail-fields"><template v-for="f in config.fields.filter(f=>!['password','locationIds','locationId','therapistId','price'].includes(f.key))" :key="f.key"><div><span>{{ f.label }}</span><strong>{{ f.type==='checkbox'?(record[f.key]?'Ya':'Tidak'):record[f.key]||'—' }}</strong></div></template><div v-if="record.locations"><span>Lokasi kerja</span><strong>{{ record.locations.map(l=>l.name).join(', ') }}</strong></div></div><template v-if="resource==='services'"><h3 class="mt-6">Daftar harga</h3><div v-for="p in record.prices.filter(p=>p.isActive)" :key="p.id" class="billing-line"><span>{{ p.locationId?'Lokasi #'+p.locationId:'Harga umum' }}</span><strong>{{ money(p.price) }}</strong></div></template></section><TherapistSchedulePanel v-if="resource==='therapists'&&canAssign" :therapist="record" /><UiModal :open="addressOpen" title="Alamat customer" @close="addressOpen=false"><form @submit.prevent="saveAddress"><label>Label<input v-model="address.label" required placeholder="Home, Villa, Hotel…" /></label><label>Alamat<textarea v-model="address.address" required minlength="3" rows="3" /></label><LocationPicker v-model="addressPin" :address="address.address" /><label>Catatan<input v-model="address.notes" /></label><label class="checkbox-label"><input v-model="address.isDefault" type="checkbox" />Jadikan alamat utama</label><p v-if="message" class="error-message">{{ message }}</p><div class="modal-actions"><UiButton variant="secondary" @click="addressOpen=false">Batal</UiButton><UiButton type="submit" :loading="busy">Simpan alamat</UiButton></div></form></UiModal><UiModal :open="deleteOpen" title="Hapus customer?" @close="deleteOpen=false"><p>Customer tanpa histori order dapat dihapus. Tindakan ini juga menghapus alamatnya.</p><p v-if="message" class="error-message">{{ message }}</p><div class="modal-actions"><UiButton variant="secondary" @click="deleteOpen=false">Batal</UiButton><UiButton variant="danger" :loading="busy" @click="remove">Hapus customer</UiButton></div></UiModal></div><UiEmptyState v-else title="Data tidak ditemukan" :message="error?.data?.statusMessage" /></template>